import { mkdir } from 'node:fs/promises'
import { join } from 'node:path'
import { COMPONENTS, type ComponentConfig } from './manifest'

const GENERATED_HEADER = `/**
 * @generated by Cerberus CLI
 * This file is auto-generated. Do not edit this file manually.
 */

`

const REF_URL = 'https://cerberus.digitalu.design/docs/components'

function capitalize(str: string): string {
  return str.charAt(0).toUpperCase() + str.slice(1)
}

async function generateComponentAPI(config: ComponentConfig) {
  const {
    name,
    key,
    anatomy,
    description,
    isArkUI = true,
    abstractions = [],
    types = [],
  } = config

  const outputDir = join(process.cwd(), 'src', 'components', key)
  await mkdir(outputDir, { recursive: true })

  const parts = Array.isArray(anatomy)
    ? [...anatomy]
    : (anatomy as { keys: () => string[] }).keys()

  // --- 1. Generate primitives.tsx (Ark UI components only) ---
  if (isArkUI) {
    let primitivesCode = `${GENERATED_HEADER}'use client'\n\n`
    primitivesCode += `import { ${name} as Ark${name} } from '@ark-ui/react/${key}'\n`
    primitivesCode += `import { type ComponentProps, createSlotRecipeContext } from 'styled-system/jsx'\n`
    primitivesCode += `import { ${key} } from 'styled-system/recipes'\n\n`
    primitivesCode += `const { withProvider, withContext } = createSlotRecipeContext(${key})\n\n`

    for (const part of parts) {
      const isRoot = part === 'root'
      const partName = `${name}${capitalize(part)}`
      const arkPart = `Ark${name}.${capitalize(part)}`

      primitivesCode += `// ${partName} -----------------------------------------------------\n\n`
      primitivesCode += `export type ${partName}Props = ComponentProps<typeof ${partName}>\n`
      primitivesCode += `export const ${partName} = ${isRoot ? 'withProvider' : 'withContext'}(${arkPart}, '${part}')\n\n`
    }

    await Bun.write(join(outputDir, 'primitives.tsx'), primitivesCode)
  }

  // --- 2. Generate api.ts ---
  let apiCode = GENERATED_HEADER

  // Group abstraction value imports & type re-exports by file
  const abstractionsByFile = new Map<
    string,
    { values: string[]; types: string[] }
  >()

  for (const abs of abstractions) {
    const entry = abstractionsByFile.get(abs.file) ?? { values: [], types: [] }
    entry.values.push(`${name}${abs.name}`)
    if (abs.types?.length) {
      entry.types.push(...abs.types)
    }
    abstractionsByFile.set(abs.file, entry)
  }

  for (const [file, { values, types: absTypes }] of abstractionsByFile) {
    if (values.length) {
      apiCode += `import { ${values.join(', ')} } from './${file}'\n`
    }
    if (absTypes.length) {
      apiCode += `export type { ${absTypes.join(', ')} } from './${file}'\n`
    }
  }

  // Import primitives
  if (parts.length > 0) {
    apiCode += `import {\n`
    for (const part of parts) {
      apiCode += `  ${name}${capitalize(part)},\n`
    }
    apiCode += `} from './primitives'\n\n`
  }

  // Re-export primitive types
  const primitiveTypes = isArkUI
    ? [...parts.map((part) => `${name}${capitalize(part)}Props`), ...types]
    : [...types]

  if (primitiveTypes.length > 0) {
    apiCode += `export type {\n`
    for (const typeName of primitiveTypes) {
      apiCode += `  ${typeName},\n`
    }
    apiCode += `} from './primitives'\n\n`
  }

  // --- Generate Rust-Style JSDoc ---
  const docUrl = `${REF_URL}/${key}`
  const formattedDesc = description
    .trim()
    .split('\n')
    .map((line) => (line.trim() ? ` * ${line}` : ' *'))
    .join('\n')

  let jsDoc = `/**\n`
  jsDoc += ` * ## ${name}\n`
  jsDoc += ` *\n`
  jsDoc += `${formattedDesc}\n`
  jsDoc += ` *\n`
  jsDoc += ` * For a customizable ${name}, use style props, slots, or the base-level primitives for granular control over the component's structure and behavior.\n`
  jsDoc += ` *\n`
  jsDoc += ` * ## Slots\n`
  jsDoc += ` *\n`
  jsDoc += ` * | Slot | Description |\n`
  jsDoc += ` * |------|-------------|\n`

  for (const part of parts) {
    const exportKey = part === 'root' ? 'Root' : capitalize(part)
    const desc =
      part === 'root'
        ? `The root element of the ${name} component.`
        : `The ${part} element of the ${name} component.`
    jsDoc += ` * | \`${exportKey}\` | ${desc} |\n`
  }

  for (const abs of abstractions) {
    jsDoc += ` * | \`${abs.name}\` | ${abs.description} |\n`
  }

  jsDoc += ` *\n`
  jsDoc += ` * ## Reference\n`
  jsDoc += ` *\n`
  jsDoc += ` * @see [${name} Docs](${docUrl})\n`
  jsDoc += ` */\n`

  apiCode += jsDoc

  // Determine the base component for Object.assign
  const defaultAbstraction = abstractions.find((abs) => abs.isDefaultExport)
  const fallbackRoot = parts.includes('root')
    ? `${name}Root`
    : `${name}${capitalize(parts[0])}`
  const assignTarget = defaultAbstraction
    ? `${name}${defaultAbstraction.name}`
    : fallbackRoot

  apiCode += `export const ${name} = Object.assign(${assignTarget}, {\n`

  for (const part of parts) {
    const isRoot = part === 'root'
    const exportKey = isRoot ? 'Root' : capitalize(part)
    const partName = `${name}${capitalize(part)}`
    apiCode += `  ${exportKey}: ${partName},\n`
  }

  for (const abs of abstractions) {
    apiCode += `  ${abs.name}: ${name}${abs.name},\n`
  }

  apiCode += `})\n`

  // --- 3. Write files ---
  await Bun.write(join(outputDir, 'api.ts'), apiCode)
  await Bun.write(
    join(outputDir, 'index.ts'),
    `${GENERATED_HEADER}export * from './api'\n`,
  )

  console.log(`✅ Generated ${name} API at ${outputDir}`)
}

async function run() {
  console.log('Generating Cerberus APIs...\n')
  for (const config of COMPONENTS) {
    await generateComponentAPI(config)
  }
  console.log('\n🎉 All APIs generated successfully!')
}

run().catch(console.error)
